#include <vector>
#include <cstddef>
#include <omp.h>

// In-place LU factorization without pivoting (Doolittle-style):
// After completion, A contains U in the upper triangle (including diagonal)
// and L in the lower triangle (with implicit unit diagonal).
void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    auto idx = [N](size_t i, size_t j) -> size_t { return i * N + j; };

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[idx(k, k)];
        // No pivoting: if pivot is zero (or tiny), results will be invalid / may divide by zero.

        // 1) Compute multipliers for column k: A[i,k] = A[i,k] / A[k,k] for i>k
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1);
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            A[idx(i, k)] /= pivot;
        }

        // 2) Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j] for i>k, j>k
        // Parallelize over rows to avoid any concurrent writes to the same A element.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1);
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            const double lik = A[idx(i, k)];
            const size_t rowBase = i * N;
            const size_t kBase   = k * N;

            for (size_t j = k + 1; j < N; ++j) {
                A[rowBase + j] -= lik * A[kBase + j];
            }
        }
    }
}
